import * as React from "react";

import { FrameScope, useInFrame } from "../lib/frame-context";
import { cn } from "../lib/utils";
import { Button } from "./button";
import { Code, type CodeProps } from "./code";
import { Icon, type IconSource } from "./icon";
import { Json, type JsonProps, prepareJson } from "./json";
import { MiddleTruncate } from "./middle-truncate";
import { HIDDEN_SECRET_VALUE } from "./secret-input";
import { CopyButton } from "./sensitive-editor";
import { Tooltip } from "./tooltip";

import geometry from "./button-geometry.module.css";
import styles from "./code.module.css";
import frame from "./frame.module.css";

export type CodeBlockProps = Omit<CodeProps, "children" | "block" | "onCopy" | "label"> & {
  children?: React.ReactNode;
  label?: React.ReactNode;
  icon?: IconSource;
  actions?: React.ReactNode;
  copyable?: boolean;
  copyValue?: string;
  copyLabel?: string;
  onCopy?: (value: string) => void;
  writeClipboard?: (value: string) => Promise<void>;
  /** Masks the content until the reveal toggle is pressed. Copy still writes the real value. */
  sensitive?: boolean;
};
export const CodeBlock = ({
  children,
  code,
  label,
  icon,
  actions,
  copyable = true,
  copyValue,
  copyLabel = "Copy code",
  onCopy,
  writeClipboard,
  sensitive = false,
  className,
  ...props
}: CodeBlockProps) => {
  const json =
    React.isValidElement<JsonProps>(children) && children.type === Json ? children : null;
  const shown = json
    ? prepareJson(json.props.value, json.props.redact).text
    : (code ?? (typeof children === "string" ? children : ""));
  const source = json ? shown : (copyValue ?? shown);
  const hasCopySource =
    Boolean(json) || copyValue !== undefined || code !== undefined || typeof children === "string";
  const embedded = useInFrame("CodeBlock");
  const labelText = typeof label === "string" ? label : undefined;
  const identityId = React.useId();
  const revealKey = `${shown}\u0000${source}`;
  const [revealed, setRevealed] = React.useState<string | null>(null);
  if (revealed !== null && (!sensitive || revealed !== revealKey)) setRevealed(null);
  const masked = sensitive && revealed !== revealKey;
  return (
    <section
      data-slot="code-block"
      aria-label={labelText}
      aria-labelledby={label && !labelText ? identityId : undefined}
      data-embedded={embedded || undefined}
      className={cn(!embedded && frame.frame, styles.codeBlock, className)}
    >
      <FrameScope framed>
        {(label || actions || copyable || sensitive) && (
          <div className={styles.header} data-has-actions={Boolean(actions) || undefined}>
            <div id={identityId} className={styles.identity}>
              {icon && <Icon icon={icon} />}
              {labelText ? (
                <MiddleTruncate keepEnd={16} className={styles.blockLabel}>
                  {labelText}
                </MiddleTruncate>
              ) : (
                label
              )}
            </div>
            {(actions || copyable || sensitive) && (
              <div className={styles.actions}>
                {actions}
                {sensitive && (
                  <Tooltip content={masked ? "Reveal value" : "Hide value"}>
                    <Button
                      type="button"
                      variant="ghost"
                      className={geometry.nestedAction}
                      iconOnly
                      icon={masked ? "eye" : "eye-off"}
                      aria-pressed={!masked}
                      onClick={() => setRevealed(masked ? revealKey : null)}
                    >
                      Reveal value
                    </Button>
                  </Tooltip>
                )}
                {copyable && (
                  <CopyButton
                    value={source}
                    disabled={!hasCopySource}
                    label={copyLabel}
                    iconOnly
                    onCopy={onCopy}
                    writeClipboard={writeClipboard}
                  />
                )}
              </div>
            )}
          </div>
        )}
        <div className={cn(frame.frameInset, styles.body)}>
          {masked ? (
            <Code
              block
              {...props}
              format="plain"
              code={(shown || HIDDEN_SECRET_VALUE).replace(/./gu, "•")}
              label={`${labelText ?? "Code"}, hidden`}
              aria-hidden
              data-masked=""
            />
          ) : (
            (json ??
            (typeof children === "string" || children === undefined ? (
              <Code block code={code ?? children} label={labelText} {...props} />
            ) : (
              <div className={styles.customContent}>{children}</div>
            )))
          )}
        </div>
      </FrameScope>
    </section>
  );
};

.button {
  --cipher-action-requested-height: var(--cipher-size-control-default);
  --cipher-action-height: var(--cipher-action-requested-height);
  --cipher-action-font-size: var(--cipher-type-label-font-size);
  --cipher-action-line-height: var(--cipher-type-label-line-height);
  --cipher-action-inset: var(--cipher-space-control-inline);
  --cipher-action-icon-size: var(--cipher-size-icon-label);
  --cipher-action-border: var(--cipher-size-control-border);
  --cipher-kbd-host-block: calc(var(--cipher-action-height) - 2 * var(--cipher-action-border));
  --cipher-kbd-host-end: var(--cipher-action-inset);
  box-sizing: border-box;
  min-height: var(--cipher-action-height);
  gap: var(--cipher-space-control-gap);
  padding-block: calc(
    (var(--cipher-action-height) - var(--cipher-action-line-height)) / 2 -
      var(--cipher-action-border)
  );
  padding-inline: calc(
    var(--cipher-action-inset) + var(--cipher-size-control-border) - var(--cipher-action-border)
  );
  border-width: var(--cipher-action-border);
  border-radius: 0;
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-action-font-size);
  line-height: var(--cipher-action-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-label-letter-spacing);
  cursor: default;
}
/* The accent face lights its edges with inset shadows, which paint inside the border, so it trades the border for padding to light the whole face at the same size. */
@media (forced-colors: none) {
  .button[data-cipher-button-material] {
    --cipher-action-border: 0px;
  }
}
a.button[href]:not([aria-busy="true"]) {
  cursor: pointer;
}
.default {
  --cipher-action-requested-height: var(--cipher-size-control-default);
  --cipher-action-inset: var(--cipher-space-control-inline-sm);
}
.iconOnly:where(.default) {
  --cipher-action-icon-size: var(--cipher-size-icon-sm);
}
.regular {
  --cipher-action-requested-height: var(--cipher-size-control-md);
}
.large {
  --cipher-action-requested-height: var(--cipher-size-control-lg);
  --cipher-action-inset: var(--cipher-space-16);
}
.extraSmall,
.iconExtraSmall {
  --cipher-action-requested-height: var(--cipher-size-control-xs);
  --cipher-action-icon-size: var(--cipher-size-icon-caption);
  --cipher-action-font-size: var(--cipher-type-caption-font-size);
  --cipher-action-line-height: var(--cipher-type-caption-line-height);
  --cipher-action-inset: var(--cipher-space-6);
}
.icon {
  --cipher-action-requested-height: var(--cipher-size-nested-lg);
}
.iconSmall {
  --cipher-action-requested-height: var(--cipher-size-nested-md);
}
.iconLarge {
  --cipher-action-requested-height: var(--cipher-size-control-lg);
}
.iconRow {
  --cipher-action-requested-height: var(--cipher-size-target-row);
  --cipher-action-icon-size: var(--cipher-size-glyph);
}
.icon,
.iconExtraSmall,
.iconSmall,
.iconLarge,
.iconRow,
.iconOnly {
  width: var(--cipher-action-height);
  min-width: var(--cipher-action-height);
  padding-inline: 0;
}
.button svg:not([class*="size-"]) {
  width: var(--cipher-action-icon-size);
  height: var(--cipher-action-icon-size);
}
.inputGroup {
  --cipher-nested-action-height: var(--cipher-size-nested-default);
}
.inputGroup[data-size="xs"] {
  --cipher-nested-action-height: var(--cipher-field-nested);
}
.inputGroup[data-size="sm"] {
  --cipher-nested-action-height: var(--cipher-size-nested-sm);
}
.inputGroup[data-size="md"] {
  --cipher-nested-action-height: var(--cipher-size-nested-md);
}
.inputGroup[data-size="lg"] {
  --cipher-nested-action-height: var(--cipher-size-nested-lg);
}
.nestedAction {
  --cipher-action-height: min(
    var(--cipher-action-requested-height),
    var(--cipher-nested-action-height, var(--cipher-action-requested-height))
  );
}
.inputGroup > [data-slot="input-group-addon"][data-align="inline-start"][data-has-button] {
  padding-inline-start: var(--cipher-space-control-slot-inset);
}
.inputGroup > [data-slot="input-group-addon"][data-align="inline-end"][data-has-button] {
  padding-inline-end: var(--cipher-space-control-slot-inset);
}
.badged[data-cipher-button] {
  position: relative;
  overflow: visible;
}
.cornerBadge {
  position: absolute;
  top: calc(var(--cipher-action-border) / -2);
  inset-inline-end: calc(-1 * var(--cipher-action-border));
  z-index: 1;
  display: inline-flex;
  translate: 0 -50%;
  background: var(--cipher-surface);
  box-shadow: 0 0 0 var(--cipher-space-2) var(--cipher-surface);
  pointer-events: none;
}
[data-framed] .cornerBadge {
  background: var(--cipher-tint);
  box-shadow: 0 0 0 var(--cipher-space-2) var(--cipher-tint);
}
.applied[data-cipher-button] {
  position: relative;
}
.applied.applied[data-cipher-button] {
  color: var(--cipher-ink);
}
.appliedDot {
  position: absolute;
  top: var(--cipher-space-4);
  right: var(--cipher-space-4);
  width: var(--cipher-size-unread);
  height: var(--cipher-size-unread);
  border-radius: 0;
  background: var(--cipher-accent-fg);
  box-shadow: 0 0 0 var(--cipher-space-2) var(--cipher-surface);
  pointer-events: none;
}
[data-framed] .appliedDot {
  box-shadow: 0 0 0 var(--cipher-space-2) var(--cipher-tint);
}
.triggerLayout {
  justify-content: flex-start;
  text-align: start;
}
/* An outline trigger shows a chosen value the way a Select does, so it takes the field's body type; ghost triggers stay actions. */
.triggerLayout[data-variant="outline"] {
  font-family: var(--cipher-type-body-font-family);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.triggerLayout.regular {
  --cipher-action-inset: var(--cipher-space-control-inline-md);
}
.triggerLayout.large {
  --cipher-action-inset: var(--cipher-space-control-inline);
}
[data-cipher-button].triggerLayout > [data-press],
.triggerLayout > [data-press] > [data-slot="button-label-group"] {
  display: flex;
  flex: 1 1 auto;
  justify-content: flex-start;
  width: 100%;
}
.triggerLabel {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.triggerLayout svg.triggerChevron {
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
}
.triggerLayout:is([data-variant="outline"], [data-variant="secondary"], [data-variant="ghost"])
  .triggerChevron {
  color: var(--cipher-muted);
}
[data-cipher-button] > [data-press] [data-slot="button-text"] {
  display: contents;
}

.code {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  color: var(--cipher-text2, var(--foreground));
}
.inline {
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft, var(--border));
  border-radius: 0;
  padding: var(--cipher-space-2) var(--cipher-space-4);
  background: var(--cipher-tint, var(--muted));
  overflow-wrap: anywhere;
}
.block {
  margin: 0;
  overflow: auto;
  padding: var(--cipher-space-surface-inset);
  tab-size: 2;
  white-space: pre;
  outline-offset: -2px;
}
.wrap {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.line {
  display: inline-block;
  min-height: var(--cipher-type-mono-line-height);
  min-width: 100%;
}
.highlight {
  background: var(--cipher-accent-wash, var(--muted));
  min-width: calc(100% + 2 * var(--cipher-space-surface-inset));
  margin-inline: calc(-1 * var(--cipher-space-surface-inset));
  padding-inline: var(--cipher-space-surface-inset);
}
.number {
  display: inline-block;
  width: 3ch;
  margin-right: var(--cipher-space-content-group);
  text-align: right;
  color: var(--cipher-muted, var(--muted-foreground));
  user-select: none;
}
.codeBlock {
  container: cipher-code-block / inline-size;
  width: 100%;
}
.codeBlock > .header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-3) var(--cipher-space-4)
    calc(var(--cipher-space-12) - var(--cipher-size-control-border));
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  color: var(--cipher-text2);
}
.codeBlock > .header :global([data-slot="icon"]) {
  width: var(--cipher-size-icon-sm);
  height: var(--cipher-size-icon-sm);
  flex: none;
  color: var(--cipher-muted);
}
.body {
  overflow: hidden;
}
.identity {
  grid-column: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-control-gap);
}
/* An empty header still needs a text line so the block's baseline sits on the header, as with a label. */
.identity:empty::before {
  content: "\200b" / "";
}
.actions {
  grid-column: 2;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: end;
  gap: var(--cipher-space-control-slot-gap);
}
.actions > :global([data-slot="copy-button"]) {
  display: contents;
}
.actions > :global([data-slot="copy-button"]) > :global([data-copy-feedback]):not(:empty) {
  flex-basis: 100%;
  text-align: end;
}
.customContent {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  padding: var(--cipher-space-surface-inset);
}
.tree {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  overflow: auto;
  padding: var(--cipher-space-surface-inset);
}
.entry {
  display: flex;
  align-items: baseline;
  white-space: pre;
}
.treeCaret {
  display: inline-block;
  flex: none;
  width: var(--cipher-space-16);
}
.key {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 600;
}
.primitive {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 500;
}
.string {
  color: var(--cipher-text2, var(--foreground));
}
.punctuation {
  color: var(--cipher-muted, var(--muted-foreground));
}
.snippet {
  --cipher-nested-action-height: var(--cipher-size-nested-md);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--cipher-space-control-slot-gap);
  min-width: 0;
  border: var(--cipher-size-control-border) solid var(--cipher-control, var(--border));
  border-radius: 0;
  background: var(--cipher-surface, var(--background));
  padding: var(--cipher-space-control-slot-inset);
  padding-inline-start: var(--cipher-space-control-inline);
  min-height: var(--cipher-size-control-md);
}
.snippetSmall {
  --cipher-nested-action-height: var(--cipher-size-nested-sm);
  min-height: var(--cipher-size-control-sm);
}
.prompt {
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  user-select: none;
}
.input {
  flex: 1;
  width: 0;
  min-width: min(100%, 10ch);
  flex-basis: 10ch;
  border: 0;
  outline: none;
  background: transparent;
  color: inherit;
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.snippet[data-multiline] {
  align-items: flex-start;
}
.snippet[data-multiline] > .prompt {
  padding-block: calc((var(--cipher-nested-action-height) - 1lh) / 2);
}
/* field-sizing: content ignores rows and is missing in older targets, so the line count also sets a minimum height; content past it scrolls. */
.snippetLines {
  box-sizing: content-box;
  min-height: calc(var(--cipher-snippet-rows) * 1lh);
  max-height: calc(var(--cipher-snippet-lines) * 1lh);
  padding-block: calc((var(--cipher-nested-action-height) - 1lh) / 2);
  overflow-y: auto;
  resize: none;
  field-sizing: content;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.snippet {
  transition-property: border-color, box-shadow;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.snippet[data-input-focus] {
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.snippet > :global([data-slot="copy-button"]) {
  display: contents;
}
.snippet > :global([data-slot="copy-button"]) > :global([data-copy-feedback]):not(:empty) {
  flex-basis: 100%;
}
.token_comment {
  color: var(--cipher-muted, var(--muted-foreground));
  font-style: italic;
}
.token_string {
  color: var(--cipher-text2, var(--foreground));
}
.token_keyword,
.token_number {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 500;
}
.token_key {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 600;
}
.blockLabel {
  flex: 1;
  width: auto;
}
.treeNode {
  min-width: 0;
}
.treeToggle {
  display: inline-flex;
  align-items: center;
  min-width: var(--cipher-size-nested-sm);
  min-height: var(--cipher-size-nested-sm);
  text-align: start;
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
}
.treeToggle:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.treeChildren {
  margin-left: calc(var(--cipher-space-6) - var(--cipher-size-control-border));
  padding-left: var(--cipher-space-10);
  border-left: var(--cipher-size-control-border) solid var(--cipher-line);
}
.notice {
  margin: var(--cipher-space-8) 0;
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.wrap .entry {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
@container cipher-code-block (max-width: 30rem) {
  .header[data-has-actions] .identity,
  .header[data-has-actions] .actions {
    grid-column: 1 / -1;
  }
  .header[data-has-actions] .identity:empty {
    display: none;
  }
  .header[data-has-actions] .actions {
    justify-content: start;
  }
}

.frame {
  --cipher-frame-pad: var(--cipher-space-3);
  --cipher-frame-inner-radius: 0;
  min-width: 0;
  padding: var(--cipher-frame-pad);
  background: var(--cipher-tint);
  border: 0;
  border-radius: 0;
}
.frame[data-frame-head] {
  padding-top: 0;
}
.frame[data-frame-foot] {
  padding-bottom: 0;
}
.frameFoot[hidden] {
  display: none;
}
.frameHead,
.frameFoot.frameFoot,
.frameToolbar {
  --cipher-size-control-default: var(--cipher-size-control-band);
}
/* A band holds one control height: an explicit size on a band action only skews it against its
   neighbours, so every action takes the band tier. Slot buttons inside a field keep their own size. */
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button]:not(:is([data-field-box], [data-slot="input-group"]) *) {
  --cipher-action-requested-height: var(--cipher-size-control-band);
  --cipher-button-icon-size: var(--cipher-size-icon-sm);
}
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button]:is([data-size="xs"], [data-size="md"], [data-size="lg"]):not(
    :is([data-field-box], [data-slot="input-group"]) *
  ) {
  --cipher-action-font-size: var(--cipher-type-label-font-size);
  --cipher-action-line-height: var(--cipher-type-label-line-height);
  --cipher-action-inset: var(--cipher-space-control-inline-sm);
  --cipher-action-icon-size: var(--cipher-size-icon-label);
}
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button][data-icon-only]:is([data-size="xs"], [data-size="md"], [data-size="lg"]):not(
    :is([data-field-box], [data-slot="input-group"]) *
  ) {
  --cipher-action-icon-size: var(--cipher-size-icon-sm);
}
:is(.frameHead, .frameFoot.frameFoot, .frameToolbar)
  [data-cipher-button][data-size="icon-xs"]:not(:is([data-field-box], [data-slot="input-group"]) *) {
  --cipher-action-icon-size: var(--cipher-size-icon-sm);
}
.frameFoot.frameFoot {
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-6) var(--cipher-space-frame-inline);
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
  border: 0;
  color: var(--cipher-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
}
.frameHead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  justify-content: space-between;
  gap: var(--cipher-space-4) var(--cipher-space-12);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-frame-inline);
  min-width: 0;
}
.frameHead[data-select] {
  padding-inline-start: calc(var(--cipher-space-frame-inline) + var(--cipher-space-frame-title-inline));
}
.frameHead[data-select] > .frameTitle,
.frameHead[data-select] > * > .frameTitle:first-child {
  margin-inline-start: 0;
}
.frameTitle {
  flex: 1 1 var(--cipher-size-cell-min);
  min-width: 0;
  margin-inline-start: var(--cipher-space-frame-title-inline);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--cipher-muted);
  text-transform: uppercase;
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
}
.frameTitle[data-hint] {
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
  margin-inline-start: calc(var(--cipher-space-frame-title-inline) - var(--cipher-focus-clearance));
}
.frameTitleHint {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-color: var(--cipher-faint);
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
.frameAction {
  flex: none;
  margin-inline-start: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  color: var(--cipher-text2);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-label-font-weight);
}
.frameAction > a:not([data-slot]) {
  color: var(--cipher-link);
  text-decoration: underline;
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
.frameAction > a:not([data-slot]):hover {
  color: var(--cipher-text2);
  text-decoration-thickness: var(--cipher-space-2);
}
.frameInset {
  min-width: 0;
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: var(--cipher-frame-inner-radius);
  box-shadow: var(--cipher-shadow-raised);
}
